return $input.all().map((item, index) => ({
  json: {
    ...item.json,
    edgeUrl: '{{PROSPECT_DESK_SUPABASE_URL}}/functions/v1/outreach',

    airtableSyncWorkflowId: '{{PROSPECT_DESK_AIRTABLE_SYNC_WORKFLOW_ID}}',
  },
  pairedItem: { item: index },
}));

function header(item, name) {
  const expected = name.toLowerCase();
  const found = Object.entries(item).find(([key]) => key.toLowerCase() === expected);
  return typeof found?.[1] === 'string' ? found[1] : '';
}
return $input.all().flatMap(({ json }, index) => {
  const rawSender = header(json, 'From');
  const sender = (rawSender.match(/<([^<>]+)>/)?.[1] ?? rawSender).trim().toLowerCase();
  const labels = json.labelIds ?? (json.labels ?? []).map(label => label.id ?? label.name);
  if (typeof json.id !== 'string' || typeof json.threadId !== 'string' ||
    !/^[^\s@<>,;]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(sender) ||
    labels.some(label => ['SENT', 'DRAFT', 'SPAM', 'TRASH'].includes(String(label).toUpperCase()))) return [];
  const timestamp = Number(json.internalDate);
  return [{ json: { messageId: json.id, threadId: json.threadId, sender,
    receivedAt: Number.isFinite(timestamp) && timestamp > 0 ? new Date(timestamp).toISOString() : null,
  }, pairedItem: { item: index } }];
});

function header(item, name) {
  const value = item.headers?.[name];
  return typeof value === 'string' ? value.replace(new RegExp('^' + name + ':\\s*', 'i'), '').trim().toLowerCase() : '';
}
return $input.all().flatMap(({ json }, index) => {
  const original = $('Read Gmail Metadata').itemMatching(index).json;
  const match = $('Match Outreach Thread').itemMatching(index).json;
  const automated = header(json, 'auto-submitted');
  if ((automated && automated !== 'no') || header(json, 'content-type').includes('multipart/report') ||
    header(json, 'x-autoreply') || header(json, 'x-autorespond')) return [];

  const sender = json.from?.value?.[0]?.address?.trim().toLowerCase();
  const text = typeof json.text === 'string' ? json.text.trim().slice(0, 12000) : '';
  if (json.id !== original.messageId || json.threadId !== original.threadId || sender !== original.sender || !text) return [];
  const parsedDate = new Date(json.date ?? '');
  const receivedAt = original.receivedAt ?? (Number.isFinite(parsedDate.valueOf()) ? parsedDate.toISOString() : new Date().toISOString());
  return [{ json: { sendItemId: match.sendItemId, ...original, receivedAt, message: text }, pairedItem: { item: index } }];
});

return $input.all().flatMap(({ json }, index) => {
  if (!json.needsTriage || !json.replyId || typeof json.message !== 'string') return [];
  const replyText = json.message.replace(/\r\n?/g, '\n')
    .split(/^[ \t]*(?:On [\s\S]{1,300}? wrote:|[- ]+(?:Original Message|Forwarded message)[- ]+)[ \t]*$/im)[0]
    .split('\n').filter(line => !/^\s*>/.test(line)).join('\n').trim();
  return [{ json: { replyId: json.replyId, replyText }, pairedItem: { item: index } }];
});

const interestedOutcomes = ['Hot', 'Warm', 'Needs nurture'];
const validOutcomes = [...interestedOutcomes, 'Do not contact', 'No interest shown'];

return $input.all().map(({ json: response }, index) => {
  const { replyId, replyText } = $('Prepare Triage').itemMatching(index).json;
  let outcome = replyText ? 'failed' : 'No interest shown';
  if (replyText && response.status === 'completed') {
    let answer = response.output?.find(item => item.type === 'message')
      ?.content?.find(part => part.type === 'output_text')?.text;
    if (typeof answer === 'string') {
      try {
        answer = JSON.parse(answer);
      } catch {
        answer = null;
      }
    }
    if (validOutcomes.includes(answer?.outcome)) outcome = answer.outcome;
  }
  return { json: { replyId, outcome, interestConfirmed: interestedOutcomes.includes(outcome) }, pairedItem: { item: index } };
});

if (!$('Workflow settings').first().json.airtableSyncWorkflowId) return [];
const qualifyingItem = $input.all().findIndex(({ json }) => json.airtableQueued === true);
return qualifyingItem < 0 ? [] : [{ json: {}, pairedItem: { item: qualifyingItem } }];

